// SetMemberRole changes a member's role. An organization keeps at least one owner: demoting the last one is ErrLastOwner.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	return s.SetMemberRoleIf(orgID, userID, role, nil)
}

// SetMemberRoleIf is SetMemberRole, but first asks allow, if not nil, about the member as they are; allow runs under the
// store's lock, so its decision holds for the change. A refusal is returned as is.
func (s *Store) SetMemberRoleIf(orgID, userID string, role Role, allow func(cur Member) error) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	if allow != nil {
		if err := allow(m); err != nil {
			return Member{}, err
		}
	}
	if m.Role == RoleOwner && role != RoleOwner && s.ownerCount(orgID) == 1 {
		return Member{}, ErrLastOwner
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

