200	// listAPIKeys lists the organization's keys for owners and admins, and only the caller's own keys for everyone else.
201	func (s *Server) listAPIKeys(w http.ResponseWriter, r *http.Request, p auth.Principal) {
202		items := []store.APIKey{}
203		for _, k := range s.store.APIKeys(p.OrgID) {
204			if auth.CanManageTeam(p.Role) || k.UserID == p.UserID {
205				items = append(items, k)
206			}
207		}
208		writeJSON(w, http.StatusOK, list{Items: items})
209	}
