226	// revokeAPIKey revokes a key. Anyone may revoke their own keys; owners and admins may revoke any key in the organization.
227	func (s *Server) revokeAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
228		k, ok := s.store.APIKey(p.OrgID, r.PathValue("id"))
229		if !ok {
230			writeError(w, http.StatusNotFound, "not_found", "no such object")
231			return
232		}
233		if k.UserID != p.UserID && !auth.CanManageTeam(p.Role) {
234			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins revoke other members' keys")
235			return
236		}
237		if _, err := s.store.RevokeAPIKey(p.OrgID, k.ID, s.clock.Now()); err != nil {
238			s.storeError(w, err)
239			return
240		}
241		w.WriteHeader(http.StatusNoContent)
242	}
